import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { RotateCw, ArrowRight } from 'lucide-react';
import Treemap from '../components/Treemap';
import Dropdown from '../components/Dropdown';
import Logo from '../components/Logo';
import StockTable from '../components/StockTable';
import MarketStatBar from '../components/MarketStatBar';
import { topMovers } from '../data/mockData';
import { formatFcfa, formatPct } from '../lib/format';
import type { Stock } from '../types';

const PERIODS = [
  { value: '1D', label: '1J' },
  { value: '1W', label: '1S' },
  { value: '1M', label: '1M' },
  { value: '6M', label: '6M' },
  { value: '1Y', label: '1A' },
];

const INDICES = [
  { value: 'BRVMC', label: 'BRVM Composite' },
  { value: 'BRVM30', label: 'BRVM 30' },
  { value: 'BRVMPR', label: 'BRVM Principal' },
];

export default function Home() {
  const [period, setPeriod] = useState('1D');
  const [index, setIndex] = useState('BRVMC');
  const [spinning, setSpinning] = useState(false);
  const movers = topMovers(10);

  const refresh = () => {
    setSpinning(true);
    setTimeout(() => setSpinning(false), 700);
  };

  return (
    <div data-testid="page-home">
      {/* Section 1: MARKET HEADER */}
      <section className="w-full bg-surface border-b hairline">
        <div className="mx-auto max-w-shell px-6 lg:px-10 py-10 md:py-14">
          <div className="grid grid-cols-1 lg:grid-cols-[1.2fr_1fr] gap-10 items-start">
            <div>
              <div className="flex items-center gap-2 text-[12px] font-semibold text-muted uppercase tracking-widest">
                <span className="relative inline-flex items-center justify-center w-2 h-2">
                  <span className="absolute inline-flex w-full h-full rounded-full bg-mint live-dot" />
