function MoverCard({ stock }: { stock: Stock }) {
  const positive = stock.changePct >= 0;
  return (
    <Link
      to={`/stock/${stock.ticker}`}
      className="rounded-card bg-white border hairline hover:shadow-card px-4 py-4 flex flex-col justify-between min-h-[140px] transition-shadow"
      data-testid={`mover-${stock.ticker}`}
    >
      <div className="flex items-start justify-between">
        <Logo ticker={stock.ticker} size={36} />
        <span
          className={`text-[11px] font-bold num px-2 py-0.5 rounded-pill ${
            positive
              ? 'bg-mint-light text-mint-deep'
              : stock.changePct < 0
                ? 'bg-loss-light text-loss'
                : 'bg-surface text-muted'
          }`}
        >
          {formatPct(stock.changePct)}
        </span>
      </div>
      <div className="mt-3">
        <div className="text-[13px] font-semibold truncate leading-tight">{stock.name}</div>
        <div className="text-[12px] text-muted num mt-0.5">{stock.ticker}</div>
        <div className="text-[15px] font-bold num mt-2">{formatFcfa(stock.price)}</div>
      </div>
    </Link>
  );
}

function LegendSwatch({ label, color }: { label: string; color: string }) {
  return (
    <div className="flex items-center gap-1.5">
      <span className="w-3 h-3 rounded-sm" style={{ background: color }} />
      <span>{label}</span>
    </div>
  );
}

function IndexSparkline() {
  const points = [30, 34, 29, 36, 42, 38, 46, 44, 50, 48, 55, 60, 58, 64, 62, 68];
  const w = 500;
  const h = 140;
  const min = Math.min(...points);
  const max = Math.max(...points);
  const line = points
    .map((v, i) => {
      const x = (i / (points.length - 1)) * (w - 4) + 2;
      const y = h - ((v - min) / (max - min || 1)) * (h - 12) - 6;
      return `${i === 0 ? 'M' : 'L'} ${x.toFixed(1)} ${y.toFixed(1)}`;
    })
    .join(' ');
  const area = `${line} L ${w - 2} ${h} L 2 ${h} Z`;

  return (
    <div className="w-full">
      <svg viewBox={`0 0 ${w} ${h}`} className="w-full h-[140px]" preserveAspectRatio="none">
        <defs>
          <linearGradient id="index-grad" x1="0" x2="0" y1="0" y2="1">
            <stop offset="0%" stopColor="#00D084" stopOpacity="0.28" />
            <stop offset="100%" stopColor="#00D084" stopOpacity="0" />
          </linearGradient>
        </defs>
        <path d={area} fill="url(#index-grad)" />
        <path
          d={line}
          stroke="#00A468"
          strokeWidth="2"
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    </div>
  );
}
